<script lang="ts">
  import {searchableSelect} from '#lib/client/searchable-select.ts';
 import type{DesignSnapshot,DesignElement}from'@schubert/contracts';
 import{projectDesign,measurementIds,worldPoint,type DesignView,type ViewShape}from'@schubert/geometry';
 let{current,other,currentName,otherName,approvals=[],library=[],onselect}:{current:DesignSnapshot;other:DesignSnapshot;currentName:string;otherName:string;approvals?:any[];library?:any[];onselect:(id:string)=>void}=$props();
 let dialog:HTMLDialogElement,view:DesignView=$state('top'),zoom=$state(1),limit=$state(50);
 const phaseNames={planned:'Geplant',existing:'Bestand',demolition:'Rückbau'};
 function signature(s:DesignSnapshot,e:DesignElement){return{
  layout:JSON.stringify({parentId:e.parentId,transform:'transform'in e?e.transform:null,point:'point'in e?e.point:null,start:'start'in e?e.start:null,end:'end'in e?e.end:null,wall:'wallId'in e?e.wallId:null,nodes:e.kind==='wall'?[worldPoint(s,e.startNodeId),worldPoint(s,e.endNodeId)]:null,originUV:e.kind==='inscription'?e.originUV:null}),
  geometry:JSON.stringify({contour:e.kind==='stone_piece'?e.finishedContour:e.kind==='catalog_object'?e.footprint:'contour'in e?e.contour:null,measures:measurementIds(e).map(id=>({value:s.measurements[id]?.valueMm,meaning:s.measurements[id]?.semantic,review:s.measurements[id]?.reviewStatus})),boundary:e.kind==='room'?e.boundary:null,join:e.kind==='wall'?e.joinStyle:null}),
  material:JSON.stringify({material:'materialSpecVersionId'in e?e.materialSpecVersionId:null,finish:'finishSpecVersionId'in e?e.finishSpecVersionId:null,layers:'layers'in e?e.layers:null,floors:e.kind==='room'?e.floorLayers:null,substrate:e.kind==='surface'?e.substrateVersionId:null,edges:e.kind==='stone_piece'?e.edgeTreatments:null}),
  product:JSON.stringify({version:e.kind==='catalog_object'?e.productVariantVersionId:null,asset:e.kind==='catalog_object'?e.assetVersionId:null,font:e.kind==='inscription'?e.fontVariantVersionId:null,article:e.kind==='inscription'?e.materialArticleReference:null}),
  text:e.kind==='inscription'?e.exactText:e.kind==='technical_note'?e.text:'',phase:e.phase,source:JSON.stringify(e.sourceEvidenceVersionIds),label:e.label};}
 const differences=$derived.by(()=>{const before=new Map(other.elements.map(e=>[e.id,e])),rows:Array<{id:string;label:string;changes:string[];current:boolean}>=[];for(const e of current.elements){const old=before.get(e.id);if(!old){rows.push({id:e.id,label:e.label,changes:['Neu im aktuellen Stand'],current:true});continue;}before.delete(e.id);const a=signature(current,e),b=signature(other,old),changes:string[]=[];for(const[key,label]of Object.entries({layout:'Lage / Bezug',geometry:'Maße / Geometrie',material:'Material / Aufbau',product:'Produkt / Schrift',text:'Wörtlicher Inhalt',source:'Quellen',label:'Bezeichnung'}))if(a[key as keyof typeof a]!==b[key as keyof typeof b])changes.push(label);if(a.phase!==b.phase)changes.push(`Phase: ${phaseNames[b.phase]} → ${phaseNames[a.phase]}`);if(changes.length)rows.push({id:e.id,label:e.label,changes,current:true});}for(const e of before.values())rows.push({id:e.id,label:e.label,changes:['Im aktuellen Stand entfallen'],current:false});return rows;});
 const changedIds=$derived(new Set(differences.map(row=>row.id)));
 const left=$derived(projectDesign(current,view)),right=$derived(projectDesign(other,view));
 const box=$derived.by(()=>{const minX=Math.min(left.bounds.minX,right.bounds.minX),minY=Math.min(left.bounds.minY,right.bounds.minY),maxX=Math.max(left.bounds.maxX,right.bounds.maxX),maxY=Math.max(left.bounds.maxY,right.bounds.maxY),pad=Math.max(maxX-minX,maxY-minY)*.06+10;return{x:minX-pad,y:-maxY-pad,w:Math.max(1,maxX-minX)+pad*2,h:Math.max(1,maxY-minY)+pad*2};});
 function path(shape:ViewShape){const ring=(points:ViewShape['points'],closed:boolean)=>points.map((p,i)=>`${i?'L':'M'}${p.xMm},${-Number(p.yMm)}`).join(' ')+(closed?'Z':'');return ring(shape.points,shape.closed)+' '+shape.holes.map(h=>ring(h,true)).join(' ');}
 function approval(id:string){const labels={design:'Gestaltung',inscription:'Wortlaut',technical:'Technik'};const kinds=[...new Set(approvals.filter(a=>a.revision_id===id&&a.status==='approved').map(a=>labels[a.kind as keyof typeof labels]??'Dokumentierte Prüfung'))];return kinds.length?kinds.join(' · '):'Keine Zustimmung für genau diese Revision dokumentiert';}
 function references(s:DesignSnapshot){const result=new Map<string,{id:string;label:string;href:string}>();function add(id:string|null|undefined,kind:string,slug:string){if(!id||id.startsWith('unassigned'))return;const source=library.find(r=>(r.id??r.version_id)===id);result.set(id,{id,label:source?.name??source?.title??`Gespeicherter ${kind}stand`,href:`/${slug}/${id}`});}for(const e of s.elements){if('materialSpecVersionId'in e)add(e.materialSpecVersionId,'Material','material-versions');if('finishSpecVersionId'in e)add(e.finishSpecVersionId,'Oberflächen','finishes');if(e.kind==='catalog_object')add(e.productVariantVersionId,'Produkt','product-versions');if(e.kind==='inscription')add(e.fontVariantVersionId,'Schrift','fonts');for(const layer of('layers'in e?e.layers:e.kind==='room'?e.floorLayers:[]))add(layer.materialSpecVersionId,'Material','material-versions');}return[...result.values()];}
 const currentRefs=$derived(references(current)),otherRefs=$derived(references(other));
 function open(){view=current.kind==='memorial'?'front':'top';zoom=1;dialog.showModal();}
</script>
<section class="comparison-details"><h3>Planung und Freigaben</h3><dl><dt>{currentName}</dt><dd>{approval(current.revisionId)}</dd><dt>{otherName}</dt><dd>{approval(other.revisionId)}</dd></dl><button type="button" class="btn small" onclick={open}>Pläne nebeneinander ansehen</button>
 <details><summary>Materialien und Produktstände</summary>{#each [{name:currentName,refs:currentRefs},{name:otherName,refs:otherRefs}] as pair}<h4>{pair.name}</h4><ul>{#each pair.refs as ref}<li><a href={ref.href} target="_blank" rel="noreferrer">{ref.label}</a></li>{:else}<li>Konkrete Material-/Herstellerfassungen noch nicht zugeordnet.</li>{/each}</ul>{/each}</details>
 <h3>{differences.length} Unterschiede im Plan</h3><p class="hint">Verglichen werden die gewählten unveränderlichen Stände einschließlich gebundener Maße. Änderungen an Freigaben beziehen sich immer auf ihre eigene Revision.</p><ul class="differences">{#each differences.slice(0,limit) as row}<li><strong>{row.label}</strong><span>{row.changes.join(' · ')}</span>{#if row.current}<button type="button" onclick={()=>onselect(row.id)}>Element im aktuellen Plan öffnen</button>{/if}</li>{:else}<li>Layout, Maße, Material- und Produktbezüge sowie Wortlaut sind in diesen Ständen gleich.</li>{/each}</ul>{#if differences.length>limit}<button class="btn small" type="button" onclick={()=>limit+=50}>Weitere Unterschiede anzeigen</button>{/if}
</section>
<dialog bind:this={dialog} aria-labelledby="comparison-title"><header><div><p>GLEICHER KOORDINATENAUSSCHNITT</p><h2 id="comparison-title">Planstände vergleichen</h2></div><button type="button" class="btn" onclick={()=>dialog.close()}>Vergleich schließen</button></header><div class="compare-controls"><label>Vergleichsansicht<select use:searchableSelect={view} bind:value={view}><option value="top">Grundriss / Draufsicht</option><option value="front">Front</option><option value="side">Seite</option></select></label><div><button type="button" class="btn" disabled={zoom<=1} onclick={()=>zoom=Math.max(1,zoom/1.5)}>Vergleich verkleinern</button><span>{Math.round(zoom*100)} %</span><button type="button" class="btn" disabled={zoom>=6} onclick={()=>zoom=Math.min(6,zoom*1.5)}>Vergleich vergrößern</button><button type="button" class="btn" onclick={()=>zoom=1}>Vergleich einpassen</button></div></div><p class="comparison-caption">Beide Pläne verwenden denselben Maßstab im sichtbaren Ausschnitt. Dunkle Konturen markieren geänderte Elemente; die Liste nennt deren Änderungen. Schrift- und Hinweispunkte bleiben Markierungen, keine nachgebildeten Herstellerzeichen.</p><div class="drawings">{#each [{name:currentName,projection:left},{name:otherName,projection:right}] as pair}<article><h3>{pair.name}</h3><div class="drawing-scroll"><svg width={zoom*100+'%'} viewBox={`${box.x} ${box.y} ${box.w} ${box.h}`} role="img" aria-label={'Technische Vergleichsansicht · '+pair.name}>{#each pair.projection.shapes as shape}{#if shape.points.length===1}<circle cx={shape.points[0].xMm} cy={-Number(shape.points[0].yMm)} r={box.w/450} fill={changedIds.has(shape.elementId)?'#315c4c':'#aeb8ad'}/>{:else}<path d={path(shape)} fill={shape.closed&&!shape.secondary&&shape.kind!=='machining'&&shape.kind!=='clearance'?'#f0f2eb':'none'} fill-rule="evenodd" stroke={changedIds.has(shape.elementId)?'#315c4c':'#8c978b'} stroke-width={changedIds.has(shape.elementId)?1.8:1} vector-effect="non-scaling-stroke" stroke-dasharray={shape.secondary||shape.estimated?'5 4':undefined}><title>{shape.label}</title></path>{/if}{/each}</svg></div></article>{/each}</div><footer><button class="btn" type="button" onclick={()=>dialog.close()}>Zurück zur Unterschiedsliste</button></footer></dialog>
<style>.comparison-details{margin-top:24px;border-top:1px solid var(--line);padding-top:20px;font-size:13px;line-height:1.7}.comparison-details h3{font-size:15px;font-weight:600;margin:20px 0 12px}.comparison-details h4{font-size:13px;font-weight:600;margin:16px 0 8px}.comparison-details dl{font-size:12px;margin:0 0 16px}.comparison-details dt{font-weight:600;margin-top:12px}.comparison-details dd{margin:3px 0 0;color:var(--muted)}.comparison-details details{margin:20px 0}.comparison-details summary{font-size:13px;color:var(--forest);cursor:pointer}.comparison-details ul{padding:0;list-style:none}.comparison-details a{font-size:12px;color:var(--forest);overflow-wrap:anywhere}.differences li{padding:14px 0;border-bottom:1px solid var(--line)}.differences strong,.differences span{display:block;font-size:12px}.differences span{color:var(--muted);margin-top:5px}.differences button{background:none;border:0;padding:8px 0;min-height:40px;font:inherit;font-size:12px;color:var(--forest);text-align:left;cursor:pointer}.hint{font-size:12px;color:var(--muted)}.btn{min-height:44px;font-size:12px}dialog{width:min(1280px,96vw);max-height:94dvh;padding:0;border:1px solid var(--line);border-radius:6px;color:var(--ink);background:var(--paper)}dialog::backdrop{background:#15231fcc;backdrop-filter:blur(3px)}dialog header{display:flex;justify-content:space-between;align-items:center;gap:18px;padding:22px 28px;border-bottom:1px solid var(--line)}dialog header p{font-size:11px;letter-spacing:.09em;color:var(--muted)}dialog h2{font-size:24px;font-weight:500;margin:7px 0}.compare-controls{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;padding:20px 28px}.compare-controls label{font-size:13px}.compare-controls select{display:block;min-height:44px;padding:9px;font:inherit;border:1px solid var(--line);background:var(--paper);border-radius:4px;margin-top:7px}.compare-controls>div{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.compare-controls span{font-size:13px}.comparison-caption{font-size:12px;line-height:1.7;margin:0;padding:0 28px 20px;color:var(--muted)}.drawings{display:grid;grid-template-columns:1fr 1fr;gap:20px;padding:0 28px 28px}.drawings article{min-width:0;border:1px solid #d9deda;background:white}.drawings h3{font-size:14px;font-weight:600;padding:15px;margin:0;border-bottom:1px solid var(--line)}.drawing-scroll{overflow:auto;height:min(55vh,600px)}.drawing-scroll svg{display:block;min-height:100%;aspect-ratio:1.3}dialog footer{padding:18px 28px;border-top:1px solid var(--line);text-align:right}button:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid var(--forest);outline-offset:3px}@media(max-width:720px){.drawings{grid-template-columns:1fr;padding:0 18px 18px}.compare-controls,dialog header{padding:18px}.comparison-caption{padding:0 18px 18px}.btn,.differences button{min-height:48px}.compare-controls select{font-size:16px;min-height:48px}.drawing-scroll{height:45vh}}
</style>
